sys_variable_value.value:
(function execute(inputs, outputs) {
    var ota = new GlideRecord('x_snc_duty_travel_ota');
    var ota_collection = [];
    ota.addEncodedQuery('country='+inputs.country.sys_id);
    ota.query();
    while(ota.next()) {
        ota_collection.push({
            alert_sysid: ota.getUniqueValue(),
            alert_num: ota.getValue('number'),
            alert_type: ota.getDisplayValue('alert'),
            alert_description: ota.getValue('alert_description'),
            alert_travel_recommendations: ota.getValue('travel_recommendations')
        });
    }
    outputs.alerts_json = JSON.stringify(ota_collection);
})(inputs, outputs);

